-- SQLite schema for the standalone Personal CMS demo. No site records are imported.
PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE IF NOT EXISTS "pages" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(50), "slug" varchar(255), "type_id" int, "info" varchar(255), "icon" varchar(255), "image" varchar(255), "video" varchar(255), "file" varchar(255), "link" varchar(255), "include" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "page_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "slug" varchar(255), "title" varchar(255), "content" text, "image" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "pagetypes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "template" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "sliders" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "type_id" int, "info" varchar(255), "image" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "slider_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "title" varchar(255), "content" text, "image" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "slidertypes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "menus" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "type_id" int, "image" varchar(255), "link" varchar(255), "parent_id" int, "page_id" int, "data_id" int, "datatype_id" int, "cat_id" int, "tag_id" int, "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "menu_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "link" varchar(255), "title" varchar(255), "image" varchar(255), "is_active" tinyint DEFAULT 1, "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "menutypes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "datas" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(50), "slug" varchar(255), "type_id" int, "info" varchar(255), "icon" varchar(255), "image" varchar(255), "video" varchar(255), "file" varchar(255), "link" varchar(255), "writer" varchar(255), "write_at" datetime, "coordinate" varchar(255), "include" varchar(255), "cat_id" int, "parent_id" int, "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "column_1" varchar(255), "column_2" varchar(255), "column_3" varchar(255), "column_4" varchar(255), "column_5" varchar(255), "column_6" varchar(255), "column_7" varchar(255), "column_8" varchar(255), "column_9" varchar(255), "created_at" timestamp, "template_id" int REFERENCES templates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS "data_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "slug" varchar(255), "title" varchar(255), "content" text, "image" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "datatypes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "slug" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "datatype_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "slug" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "cats" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "slug" varchar(255), "type_id" int, "image" varchar(255), "file" varchar(255), "link" varchar(255), "parent_id" int, "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp, "template_id" int REFERENCES templates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS "cat_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "slug" varchar(255), "title" varchar(255), "content" text, "image" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "tags" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "slug" varchar(255), "type_id" int, "icon" varchar(255), "image" varchar(255), "cat_id" int, "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "tag_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "name" varchar(255), "slug" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "users" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "email" varchar(255), "password" varchar(255), "type_id" int, "image" varchar(255), "lang_id" int, "last_login" datetime, "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp, UNIQUE(email));
CREATE TABLE IF NOT EXISTS "usertypes" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "slug" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "variables" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "variable_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" text, "row_id" int, "lang_id" int, "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "captions" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "type_id" int, "data_id" int, "filename" varchar(255), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "caption_lang" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "row_id" int, "lang_id" int, "title" varchar(255), "created_at" timestamp, UNIQUE(row_id,lang_id));
CREATE TABLE IF NOT EXISTS "langs" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(50), "slug" varchar(50), "iso_code" varchar(50), "cat" varchar(50), "tag" varchar(50), "page" varchar(50), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "templates" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "name" varchar(100), "code" varchar(32), "is_active" tinyint DEFAULT 1, "deleted" tinyint DEFAULT 0, "sort_order" int DEFAULT 50, UNIQUE(code));
CREATE TABLE IF NOT EXISTS "logs" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "task" text, "comment" text, "ip_no" varchar(45), "user_id" int, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS "errors" ("id" INTEGER PRIMARY KEY AUTOINCREMENT, "ip_no" varchar(50), "type" varchar(50), "code" varchar(50), "message" text, "file" varchar(255), "script" varchar(255), "line" varchar(50), "referer" varchar(255), "session" text, "post" text, "get" text, "created_at" timestamp);
CREATE TABLE IF NOT EXISTS contact_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, hits INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS datas_public_type ON datas(type_id,is_active,deleted,sort_order);
CREATE INDEX IF NOT EXISTS menus_public_type ON menus(type_id,is_active,deleted,sort_order);
COMMIT;
